package info.aalmoghalis.inventory;
import android.content.ContentValues;import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.ArrayList;
public final class CustomersActivity extends AppCompatActivity{
 AppDb db; ArrayList<String> rows=new ArrayList<>(); ArrayAdapter<String> adapter;
 @Override protected void onCreate(Bundle b){super.onCreate(b);db=new AppDb(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);TextView t=new TextView(this);t.setText("العملاء");t.setTextSize(20);t.setGravity(17);t.setPadding(10,18,10,18);r.addView(t);LinearLayout a=new LinearLayout(this);EditText n=new EditText(this);n.setHint("اسم العميل");EditText p=new EditText(this);p.setHint("الهاتف");Button s=new Button(this);s.setText("إضافة");a.addView(n,new LinearLayout.LayoutParams(0,60,1));a.addView(p,new LinearLayout.LayoutParams(0,60,1));a.addView(s,new LinearLayout.LayoutParams(-2,60));r.addView(a);ListView l=new ListView(this);r.addView(l,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,rows);l.setAdapter(adapter);s.setOnClickListener(v->{if(n.getText().toString().trim().isEmpty())return;ContentValues c=new ContentValues();c.put("name",n.getText().toString().trim());c.put("gsm",p.getText().toString().trim());db.getWritableDatabase().insert("customers",null,c);n.setText("");p.setText("");load();});load();}
 void load(){rows.clear();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,gsm,address FROM customers ORDER BY id",null)){while(c.moveToNext())rows.add("#"+c.getLong(0)+"  "+c.getString(1)+"  "+(c.getString(2)==null?"":c.getString(2)));}adapter.notifyDataSetChanged();}
 @Override protected void onResume(){super.onResume();if(adapter!=null)load();}
}